import {drawWaveform} from './waveform.js';
import {reveal, flash, initializeControls, setMotion, reducedMotion, syncRange} from './motion.js';
import {MixEngine, DEMO_TRACKS, SAMPLER_SOUNDS, makeDemo} from './engine.js';
import {store} from './store.js';
import {VideoMixer,parseYouTubeURL} from './video.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>{s=Math.max(0,Number(s)||0);return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;};
const engine=new MixEngine(),video=new VideoMixer();
let mode='audio',route='perform',focus=-1,locked=false,tracks=[],queue=[],sessions=[],recordings=[],selectedDeck=0,search='',filter='all',fadeSeconds=6,prepared=null,undoQueue=null,settings={haptics:true,theme:'dark',curve:'blend',stopOutgoing:true,motion:'system'},dirty=false,viewToken=0,busy=false;
let settingsDraft={...settings};
const playIcon=playing=>playing?'<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 2h3v12H3zm7 0h3v12h-3z" fill="currentColor"/></svg>':'<svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 1l11 7-11 7z" fill="currentColor"/></svg>';
const state=()=>mode==='audio'?engine:video;
const toast=(s)=>{const e=$('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),5000);};
function native(type,extra={}){window.MixlineAndroid?.postMessage(JSON.stringify({type,...extra}));}
let lastHaptic=0;function haptic(){const now=performance.now();if(now-lastHaptic<70)return;lastHaptic=now;if(settings.haptics){if(window.MixlineAndroid)native('haptic');else navigator.vibrate?.(8);}}
function error(e){console.error(e);toast(e?.message||String(e));}
const run=f=>Promise.resolve().then(f).catch(error);
const heading=(eyebrow,title,desc='',action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;
const empty=(title,desc,action)=>`<div class="empty"><span>◎</span><h2>${title}</h2><p>${desc}</p>${action||''}</div>`;
const button=(label,attr='',cls='')=>`<button class="${cls}" ${attr}>${label}</button>`;
function modal(html){if(mode==='video')video.pauseAll();$('#dialog-body').innerHTML=html;$('#dialog').showModal();reveal($('#dialog'),'dialog');}
function close(){if($('#dialog').open)$('#dialog').close();}
async function confirmAction(title,description){return new Promise(resolve=>{modal(`<h2>${esc(title)}</h2><p class="note">${esc(description)}</p><div class="two" style="margin-top:20px"><button id="confirm-no">Cancel</button><button id="confirm-yes" class="primary">Continue</button></div>`);const d=$('#dialog');let finished=false;const finish=v=>{if(finished)return;finished=true;d.removeEventListener('close',onClose);close();resolve(v);};const onClose=()=>finish(false);d.addEventListener('close',onClose);$('#confirm-no').onclick=()=>finish(false);$('#confirm-yes').onclick=()=>finish(true);});}
async function navigate(next){if(next===route&&next!=='focus')return;if(dirty&&route==='settings'&&next!=='settings'&&!await confirmAction('Discard unsaved settings?','Your saved preferences will stay in place.'))return;dirty=false;route=next;focus=next==='focus'?selectedDeck:-1;render();reveal($('#main'));window.scrollTo({top:0,behavior:'instant'});}
async function setMode(next){if(next===mode)return;if(engine.recording&&next==='video')toast('Recording continues with local audio only. Video is never recorded.');if(mode==='video')video.pauseAll();else engine.decks.forEach((_,i)=>engine.pause(i));prepared=null;mode=next;document.body.classList.toggle('video-mode',mode==='video');$('#video-stage').hidden=mode!=='video';$('#audio-mode').classList.toggle('selected',mode==='audio');$('#video-mode').classList.toggle('selected',mode==='video');if(mode==='video'){route='challenge';$('#connection').textContent='● ONLINE VIDEO';run(()=>video.init());}else{$('#connection').textContent='● OFFLINE READY';route='perform';}render();}
function art(t,i=0){const blue=t?.demo==='blue'||(!t?.demo&&i%2);return `<div class="art ${blue?'blue':''}" aria-hidden="true"><img src="assets/cover-${blue?'blue':'red'}.svg" alt=""></div>`;}
const icon=(name,size=18)=>{const paths={mixer:'M4 3v14M10 3v14M16 3v14M1 7h6M7 13h6M13 7h6',pads:'M2 2h6v6H2zM12 2h6v6h-6zM2 12h6v6H2zM12 12h6v6h-6z',fx:'M1 11h3l3-8 5 14 3-8h4',queue:'M6 5h12M6 10h12M6 15h8M2 5h.1M2 10h.1M2 15h.1',focus:'M12 2h6v6M18 2l-8 8M3 5v12h12',settings:'M10 6a4 4 0 1 0 .01 0M10 1v3M10 16v3M1 10h3M16 10h3M3.6 3.6l2 2M14.4 14.4l2 2M3.6 16.4l2-2M14.4 5.6l2-2',record:'M10 2a8 8 0 1 0 .01 0M10 6a4 4 0 1 0 .01 0',session:'M3 2h11l3 3v13H3zM6 2v6h8V2M6 12h8v6',disc:'M10 2a8 8 0 1 0 .01 0M10 8a2 2 0 1 0 .01 0',video:'M2 4h16v12H2zM8 7l5 3-5 3z',library:'M3 2h14v16H3zM6 6h8M6 10h8M6 14h4',lock:'M5 9V6a5 5 0 0 1 10 0v3M3 9h14v10H3z',arrow:'M3 10h14M12 5l5 5-5 5'};return `<svg width="${size}" height="${size}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.disc}"/></svg>`;};
function rotary(name,attr,value,min,max,step,unit='',defaultValue=0){return `<label class="rotary" style="--angle:${min<0&&max>0?(value<0?value/(-min)*135:value/max*135):-135+(value-min)/(max-min)*270}deg"><span class="rotary-title">${name}</span><span class="knob-body"><svg class="knob-scale" viewBox="0 0 80 80" aria-hidden="true"><path d="M17 63a32 32 0 1 1 46 0" fill="none" stroke="currentColor" stroke-width="1.5" stroke-dasharray="1 5"/><path d="M17 63a32 32 0 1 1 46 0" fill="none" stroke="currentColor" stroke-width="2" opacity=".3"/></svg><span class="knob-disc"><i></i></span><input type="range" ${attr} value="${value}" min="${min}" max="${max}" step="${step}" data-default="${defaultValue}" data-unit="${unit}" aria-label="${name}" title="Drag up/down; arrow keys adjust; double tap resets"></span><output>${Number(value).toFixed(1)}${unit}</output></label>`;}
function deckCard(i){const d=engine.decks[i];return `<article class="deck deck-${i}" data-deck="${i}" aria-label="Deck ${i+1}"><div class="track-head">${art(d.track,i)}<div class="track-info"><div class="deck-identity"><span class="deck-tag">DECK ${i+1}</span><span class="deck-state" data-deck-state="${i}">${d.playing?'Playing':d.track?'Ready':'Empty'}</span></div><strong>${esc(d.track?.title||'Load a track')}</strong><small>${esc(d.track?.artist||'Your library awaits')}</small></div><button data-focus="${i}" aria-label="Focus deck ${i+1}">${icon('focus',15)}</button></div><div class="wave" data-wave="${i}" tabindex="0" role="slider" aria-label="Deck ${i+1} position" aria-valuemin="0" aria-valuemax="${d.duration||0}" aria-valuenow="${d.position||0}"><canvas data-canvas="${i}"></canvas><span class="loop-flag" data-loop-flag="${i}" hidden>LOOP ACTIVE</span></div><div class="timing"><span data-time="${i}">${time(d.position)} / ${time(d.duration)}</span><span class="bpm" data-bpm="${i}">${d.bpm?d.bpm.toFixed(1):'—'} BPM</span></div><div class="platter-area"><div class="platter" data-platter="${i}" tabindex="0" role="slider" aria-label="Deck ${i+1} platter scrub" aria-valuemin="0" aria-valuemax="${d.duration||0}" aria-valuenow="${d.position||0}"><div class="strobe-ring"></div><div class="vinyl">${art(d.track,i)}<i class="record-spindle"></i></div><div class="platter-reflection"></div></div><svg class="tonearm" viewBox="0 0 60 140" aria-hidden="true"><defs><linearGradient id="arm-${i}"><stop stop-color="#252a2e"/><stop offset=".4" stop-color="#a7b0b5"/><stop offset=".55" stop-color="#4b5358"/><stop offset="1" stop-color="#11171b"/></linearGradient></defs><circle cx="38" cy="20" r="14" fill="url(#arm-${i})" stroke="#555e64"/><circle cx="38" cy="20" r="5" fill="#0a0d10"/><path d="M38 24v58q0 12-10 19l-9 10" stroke="#050709" stroke-width="8" fill="none"/><path d="M38 24v58q0 12-10 19l-9 10" stroke="url(#arm-${i})" stroke-width="5" fill="none"/><path d="M15 105l11 9-12 15-8-6z" fill="#232a2e" stroke="#7b858b"/><path d="M9 122l4 3-2 8" stroke="var(--tone)" fill="none" stroke-width="2"/></svg><span class="platter-side">${d.slip?'SLIP':'VINYL'} / 33⅓</span></div><div class="transport"><button class="cue" data-cue="${i}">CUE</button><button class="play" data-play="${i}" aria-label="${d.playing?'Pause':'Play'} deck ${i+1}">${playIcon(d.playing)}</button><button class="sync" data-sync="${i}">SYNC</button></div><div class="quick-tone">${rotary('LOW',`data-eq="${i}:low"`,d.eq.low,-30,12,.5,' dB')}${rotary('FILTER',`data-filter-knob="${i}"`,d.filter,-1,1,.01)}</div><div class="deck-tools"><label>TEMPO <output data-rate-value="${i}">${((d.rate-1)*100).toFixed(1)}%</output><input type="range" data-rate="${i}" min="0.84" max="1.16" value="${d.rate}" step="0.001" aria-label="Deck ${i+1} tempo"></label><label>LEVEL<input type="range" data-gain="${i}" min="0" max="1.5" step="0.01" value="${d.gain}" aria-label="Deck ${i+1} channel level"></label></div><div class="meter" aria-label="Deck ${i+1} measured audio level"><i data-meter="${i}"></i></div></article>`;}
function perform(){return `<div class="performance-heading"><div><span class="eyebrow">PERFORMANCE</span><h1>${focus<0?'Dual decks':`Deck ${focus+1} / Focus`}</h1></div><button data-import>${icon('library',15)} Import</button></div>${focus>=0?`<div class="companion deck-${1-focus}" data-companion="${1-focus}">${art(engine.decks[1-focus].track,1-focus)}<div><small>DECK ${2-focus} · ${engine.decks[1-focus].playing?'PLAYING':'READY'}</small><strong>${esc(engine.decks[1-focus].track?.title||'No track loaded')}</strong></div><button data-main-cue="${1-focus}">CUE</button><button data-play="${1-focus}" aria-label="Play companion deck">${playIcon(engine.decks[1-focus].playing)}</button></div>`:''}<div class="${focus>=0?'focus':''}"><div class="decks">${focus<0?[0,1].map(deckCard).join(''):deckCard(focus)}</div></div><div class="rail workspace-shortcuts">${button(`${icon('mixer')} Mixer`,'data-route="mixer"')}${button(`${icon('pads')} Pads`,'data-route="pads"')}${button(`${icon('fx')} FX`,'data-route="fx"')}${focus>=0?button(`${icon('disc')} Dual`,'data-route="perform"'):button(`${icon('queue')} Queue`,'data-route="challenge"')}</div><div class="panel"><div class="panel-title"><h2>Transition desk</h2><span class="tag">MANUAL TAKEOVER</span></div>${transitionControls()}<p class="note">Start the incoming deck, then fade. Touch the crossfader to take over.</p></div>${!tracks.length?`<div class="panel onboarding"><h2>Your first blend starts here.</h2><p class="note">Import music or try two original Mixline beats. Your collection stays on the phone.</p>${button('Load original demo pair','data-demo','primary wide')}</div>`:''}`;}

function transitionControls(){return `<div class="three"><button data-fade="0">← Fade to 1</button><label>FADE DURATION<select id="fade-seconds">${[2,4,6,8,12,16].map(n=>`<option value="${n}" ${fadeSeconds===n?'selected':''}>${n} seconds</option>`).join('')}</select></label><button data-fade="1">Fade to 2 →</button></div>`;}
function library(){const data=tracks.filter(t=>(filter==='all'||(filter==='demo'?!!t.demo:!t.demo))&&`${t.title} ${t.artist} ${t.bpm||''}`.toLowerCase().includes(search.toLowerCase()));return heading('COLLECT → PREPARE → PERFORM','Library','Import, prepare and load your music.',button('＋ Import','data-import','primary'))+`<div class="stack"><input id="search" type="search" aria-label="Search tracks" placeholder="Search tracks, artists or BPM" value="${esc(search)}"><div class="tabbar">${[['all','All',tracks.length],['local','Imported',tracks.filter(t=>!t.demo).length],['demo','Original demos',tracks.filter(t=>t.demo).length]].map(([v,l,n])=>button(`${l} (${n})`,`data-filter="${v}"`,filter===v?'selected':'')).join('')}</div></div>${search||filter!=='all'?`<div class="rail">${button('Clear filters ×','data-clear-filter')}</div>`:''}<div class="panel">${data.length?data.map((t,i)=>trackRow(t,i)).join(''):empty(tracks.length?'No matching tracks':'Your next set starts here',tracks.length?'Try a different search or clear the filters.':'Choose audio files from your phone. You can also try the original Mixline demos.',button('Load demo pair','data-demo','primary'))}</div><div class="panel"><h2>Online sources</h2><p class="note" style="margin:12px 0">Add YouTube links in Video decks. Subscription catalogs require provider integrations and are not connected in this build.</p>${button('Open video workspace','data-mode="video"')}</div>`;}
function trackRow(t,i){return `<div class="track-row">${art(t,i)}<div class="metadata"><strong>${esc(t.title)}</strong><small>${esc(t.artist||'Local import')} · ${t.bpm?`${t.bpm} BPM`:'BPM unset'}${t.demo?' · ORIGINAL DEMO':''}</small></div><div class="actions"><button data-load="0" data-id="${esc(t.id)}" class="deck-0" aria-label="Load ${esc(t.title)} on deck 1">1</button><button data-load="1" data-id="${esc(t.id)}" class="deck-1" aria-label="Load ${esc(t.title)} on deck 2">2</button><button data-prepare="${esc(t.id)}" aria-label="Prepare ${esc(t.title)}">···</button></div></div>`;}
function queueRows(){return queue.length?queue.map((t,i)=>`<div class="queue-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(t.title)}</strong><small style="display:block">${t.source==='youtube'?'YOUTUBE':'LOCAL AUDIO'} · Start ${time(t.start)} · queued</small></div><div class="queue-actions"><button data-queue-up="${i}" ${i===0?'disabled':''} aria-label="Move ${esc(t.title)} up">↑</button><button data-queue-remove="${i}" aria-label="Remove ${esc(t.title)}">×</button></div></div>`).join(''):empty('The queue is open.','Add prepared tracks or YouTube links. Load next prepares a deck without interrupting the current one.',button(mode==='video'?'＋ Add a video':'Browse library',mode==='video'?'data-add-video':'data-route="library"','primary'));}
function challenge(){const next=queue.find(t=>(mode==='video')===(t.source==='youtube'));const incoming=state().crossfade<=.5?1:0;return heading('CHALLENGE / LIVE SESSION','Challenge','Prepare the next beat. Cut or blend when you’re ready.',button('＋ Add',mode==='video'?'data-add-video':'data-route="library"'))+`<div class="next-card"><span class="eyebrow">${prepared?'PREPARED ON DECK '+(prepared.deck+1):'UP NEXT'}</span><h2>${esc(prepared?.title||next?.title||'Your next beat goes here')}</h2><p class="note">${prepared?'Loaded, waiting for your play command.':next?`Start at ${time(next.start)} · load into Deck ${incoming+1}`:'Build a queue from your collection or video links.'}</p><div class="two" style="margin-top:18px"><button class="big-action" data-next ${!next?'disabled':''}>Load next ↓</button><button class="primary big-action" data-next-cut ${!prepared?'disabled':''}>Cut now →</button></div></div><div class="panel">${transitionControls()}</div>${mode==='video'?`<div class="panel"><h2>Player recovery & repeat</h2><div class="rail">${[0,1].map(i=>button('Retry '+(i+1),`data-video-retry="${i}"`)+button('Repeat '+(i+1)+(video.decks[i].repeat?.enabled?' · On':' · Off'),`data-video-repeat="${i}" aria-pressed="${!!video.decks[i].repeat?.enabled}"`)).join('')}</div><p class="note">${[0,1].map(i=>`<a href="${esc(video.decks[i].track?video.getURL(i):'https://www.youtube.com/')}" target="_blank" rel="noopener">Open Deck ${i+1} in YouTube ↗</a>`).join(' · ')}</p><h2 style="margin-top:20px">Local instrumental layer</h2><p class="note" style="margin:10px 0">${esc(engine.decks[0].track?.title||'Load a local instrumental onto Deck 1 from Library.')} · only this local audio enters recordings.</p>${button('Play / pause local instrumental','data-local-bed','wide')}${control('LOCAL LAYER LEVEL','data-gain="0"',engine.decks[0].gain,0,1,.01)}</div>`:''}<div class="panel"><div class="panel-title"><h2>Live queue <small>${queue.length||''}</small></h2>${undoQueue?button('Undo remove','data-queue-undo'):''}</div>${queueRows()}</div>`;}
function control(name,attr,value,min,max,step,unit=''){return `<label class="control"><div><span>${name}</span><output>${Number(value).toFixed(1)}${unit}</output></div><input type="range" ${attr} value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${name}"></label>`;}
function mixer(){return heading('LEVELS & TONE','Mixer','Levels, EQ and filters for each local deck.')+`<div class="mixer-grid">${[0,1].map(i=>{const d=engine.decks[i];return `<section class="mixer-strip deck-${i}"><h2>Deck ${i+1}</h2><small>${esc(d.track?.title||'No track loaded')}</small>${['high','mid','low'].map(b=>rotary(`${b.toUpperCase()} EQ`,`data-eq="${i}:${b}"`,d.eq[b],-30,12,.5,' dB')).join('')}${rotary('FILTER',`data-filter-knob="${i}"`,d.filter,-1,1,.01)}${control('CHANNEL',`data-gain="${i}"`,d.gain,0,1.5,.01)}<div class="meter"><i data-meter="${i}"></i></div>${button('Reset channel',`data-reset-channel="${i}"`,'wide')}</section>`;}).join('')}</div><div class="panel">${rotary('MASTER LEVEL','data-master',engine.master,0,1,.01,'',.8)}<p class="note">Master and headphone audio follow Android’s selected output. Separate headphone cueing and USB multichannel routing are not implemented.</p></div>`;}
function deckTabs(){return `<div class="tabbar">${[0,1].map(i=>button(`Deck ${i+1}`,`data-select-deck="${i}"`,selectedDeck===i?'selected':'')).join('')}</div>`;}
function pads(){const d=engine.decks[selectedDeck];return heading('CUE / LOOP / MOVE','Cues & loops','Tap an empty pad to save. Tap a saved pad to jump.')+deckTabs()+`<section class="panel deck-${selectedDeck}"><div class="panel-title"><h2>Hot cues</h2><small>${esc(d.track?.title||'Load a local track first')}</small></div><div class="pads">${d.cues.map((p,i)=>button(`${i+1}<small>${p===null?'SAVE CUE':time(p)}</small>`,`data-hotcue="${i}"`,p===null?'pad':'pad saved')).join('')}</div><div class="rail">${button('Clear cues…','data-clear-cues')}${button('Set start here','data-start-here')}${button(d.slip?'Slip · On':'Slip · Off',`data-slip aria-pressed="${!!d.slip}"`)}</div><h2 style="margin:24px 0 12px">Beat loops</h2><div class="pads">${[.25,.5,1,2,4,8,16,32].map(n=>button(`${n}<small>BEATS</small>`,`data-loop="${n}"`,d.loop&&Math.abs((d.loop.end-d.loop.start)*d.bpm/60-n)<.1?'pad saved':'pad')).join('')}</div><div class="rail">${button('Exit loop','data-loop="0"')}${button('Loop in','data-loop-in')}${button('Loop out','data-loop-out')}</div><p class="note">Loop timing uses the BPM you set. Imported tracks are not automatically analysed for tempo.</p></section><div class="panel"><h2>Beat jump</h2><div class="rail">${[-16,-4,4,16].map(n=>button(`${n>0?'+':''}${n}`,`data-jump="${n}"`)).join('')}</div><div class="two"><button data-tap>Tap tempo</button><button data-bpm-edit>Set BPM · ${d.bpm||'—'}</button></div></div>`;}
function fx(){const d=engine.decks[selectedDeck];return heading('CREATIVE TOOLS','Effects','Echo, reverb and filters for your local mix.')+deckTabs()+`<div class="panel fx-console deck-${selectedDeck}">${rotary('ECHO SEND',`data-fx="${selectedDeck}:echo"`,d.fx.echo,0,1,.01)}${rotary('REVERB SEND',`data-fx="${selectedDeck}:reverb"`,d.fx.reverb,0,1,.01)}${rotary('FILTER SWEEP',`data-filter-knob="${selectedDeck}"`,d.filter,-1,1,.01)}<div class="rail">${button('Reset effects','data-reset-fx')}${button('Echo out →','data-echo-out')}</div><p class="note">Echo out fades this deck over four seconds. Touch the crossfader to cancel the fade.</p></div><div class="panel"><h2>Original one-shots</h2><p class="note" style="margin:10px 0">Synthesized sounds, routed through the master. No sample downloads.</p><div class="pads">${SAMPLER_SOUNDS.map((s,i)=>button(s==='Closed hat'?'Hi-hat':s,`data-sample="${i}"`,'pad')).join('')}</div></div>`;}
function tools(){return heading('YOUR PERFORMANCE KIT','Tools','Mix, record and save your sessions.')+`<div class="tool-menu">${[['mixer','mixer','Mixer','Levels, EQ & filters'],['pads','pads','Pads & loops','Eight cues per deck'],['fx','fx','Effects','Echo, space & one-shots'],['record','record','Recordings','Capture your local mix'],['sessions','session','Sessions','Save and pick up later'],['settings','settings','Preferences','Make it feel right']].map(([r,iconName,name,desc])=>button(`<span>${icon(iconName,25)}</span>${name}<small>${desc}</small>`,`data-route="${r}"`)).join('')}</div><div class="panel"><h2>About this test build</h2><p class="note" style="margin-top:12px">Mixline 4.0 test 2 · standalone Android test edition.<br>Local Web Audio engine · visible official YouTube players.<br>Native low-latency DSP, pitch-preserving key lock, stems, private cue routing and connected commercial catalogs remain future development work.</p></div>`;}
function record(){return heading('CAPTURE THE MOMENT','Recordings','Capture local decks and effects. YouTube audio is excluded.')+`<div class="panel"><div class="panel-title"><h2><i class="rec-light"></i>${engine.recording?'Recording live':'Ready to record'}</h2><span class="tag">LOCAL MASTER</span></div><div class="record-time" id="record-time">${time(engine.recordingElapsed)}</div><button class="primary wide" data-record>${engine.recording?'Stop & save recording':'Start recording'}</button><p class="note" style="margin-top:14px">Recorded in your WebView’s supported format, usually WebM/Opus. Saved to this device, then exported through Android’s file picker. Maximum export size: 64 MB.</p></div><div class="panel"><h2>Saved takes</h2>${recordings.length?recordings.map(r=>`<div class="session-row"><strong>${esc(r.name)}</strong><small style="display:block">${(r.size/1048576).toFixed(1)} MB · ${esc(r.mime)}</small><div class="actions"><button data-export="${r.id}">Export recording ↓</button><button data-delete-recording="${r.id}">Delete…</button></div></div>`).join(''):empty('Nothing recorded yet','Start your local tracks, then capture your first blend.','')}</div>`;}
function sessionView(){return heading('SAVE YOUR PLACE','Sessions','Save your decks, cues and queue. Restore paused.')+`<div class="panel"><label>SESSION NAME<input id="session-name" placeholder="Friday evening set" maxlength="100"></label><button class="primary wide" style="margin-top:14px" data-save-session>Save current session</button></div><div class="panel">${sessions.length?sessions.map(s=>`<div class="session-row"><strong>${esc(s.name)}</strong><small style="display:block">Saved ${new Date(s.updated).toLocaleString()}</small><div class="actions"><button data-restore-session="${s.id}">Restore session</button><button data-delete-session="${s.id}">Delete…</button></div></div>`).join(''):empty('Room for your next set','Save the current decks and queue. Imported files stay in your collection.','')}</div>`;}
function settingsView(){settingsDraft={...settings};return heading('PERSONAL PREFERENCES','Preferences','Your controls, appearance and motion preferences.')+`<div class="panel"><div class="setting-row"><div><strong>Touch feedback</strong><small>Brief haptics for deliberate performance actions.</small></div><input data-setting="haptics" type="checkbox" aria-label="Touch feedback" ${settings.haptics?'checked':''}></div><div class="setting-row"><div><strong>Pause outgoing deck</strong><small>After a completed fade, pause the silent deck.</small></div><input data-setting="stopOutgoing" type="checkbox" aria-label="Pause outgoing deck after fade" ${settings.stopOutgoing?'checked':''}></div><div class="setting-row"><div><strong>Crossfader curve</strong><small>Blend for smooth transitions; cut for sharp swaps.</small></div><select data-setting="curve" aria-label="Crossfader curve"><option value="blend" ${settings.curve==='blend'?'selected':''}>Blend</option><option value="cut" ${settings.curve==='cut'?'selected':''}>Cut</option></select></div><div class="setting-row"><div><strong>Appearance</strong><small>Graphite for stage use; light for daylight.</small></div><select data-setting="theme" aria-label="Appearance"><option value="dark" ${settings.theme==='dark'?'selected':''}>Graphite</option><option value="light" ${settings.theme==='light'?'selected':''}>Light</option></select></div><div class="setting-row"><div><strong>Motion</strong><small>Follow your device preference or reduce animated movement.</small></div><select data-setting="motion" aria-label="Motion"><option value="system" ${(settings.motion||'system')==='system'?'selected':''}>System</option><option value="reduced" ${settings.motion==='reduced'?'selected':''}>Reduced</option></select></div><div class="rail"><button data-reset-settings>Reset defaults</button><button class="primary" data-save-settings>Save preferences</button></div><p id="settings-status" class="note">Preferences saved on this device.</p></div><div class="panel"><h2>Audio & device</h2><p class="note" style="margin:12px 0">Use your phone speaker or USB-C headphones. Android controls the active output. Phone calls, leaving the app and headphone disconnection pause playback; restart deliberately when ready.</p><button data-diagnostics>Show test diagnostics</button></div>`;}
function render(){document.body.dataset.route=route;viewToken++;const token=viewToken;$$('nav button').forEach(b=>{const active=b.dataset.route===route||b.dataset.route==='tools'&&['mixer','pads','fx','record','sessions','settings'].includes(route);b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});const views={perform,focus:perform,challenge,library,mixer,pads,fx,tools,record,sessions:sessionView,settings:settingsView};$('#main').innerHTML=(views[route]||perform)();bindGestures();initializeControls($('#main'));update();sizeVideoLayout();if(route==='sessions')store.listSessions().then(x=>{if(token===viewToken&&JSON.stringify(x)!==JSON.stringify(sessions)){sessions=x;render();}}).catch(error);if(route==='record')store.listRecordings().then(x=>{if(token===viewToken&&x.length!==recordings.length){recordings=x;render();}}).catch(error);}
async function loadTrack(i,id){if(locked)throw new Error('Unlock performance controls before loading a track.');const row=await store.getTrack(id);if(!row)throw new Error('Track missing from this device. Import it again.');if(engine.decks[i].playing&&!await confirmAction(`Replace playing Deck ${i+1}?`,'The current track will stop after the replacement has decoded successfully.'))return false;toast('Decoding audio…');const card=$(`[data-deck="${i}"]`);card?.setAttribute('aria-busy','true');card?.classList.add('loading');try{await engine.load(i,row.track,row.blob);}finally{card?.removeAttribute('aria-busy');card?.classList.remove('loading');}toast(`${row.track.title} ready on Deck ${i+1}`);haptic();render();return true;}
async function demo(){if(busy)return;busy=true;toast('Creating original demo beats…');try{for(const meta of DEMO_TRACKS){const {track,blob}=await makeDemo(meta.demo);await store.saveTrack(track,blob);}tracks=await store.listTracks();if(await loadTrack(0,DEMO_TRACKS[0].id))await loadTrack(1,DEMO_TRACKS[1].id);}finally{busy=false;render();}}
async function saveQueue(){await store.setSetting('queue',queue);}
function addVideo(){modal(`<h2>Add a YouTube beat</h2><p class="note">The official player must remain visible. Some videos do not allow embedding.</p><form id="video-form" class="stack"><label>YOUTUBE LINK<input id="video-url" type="text" required placeholder="https://youtu.be/…"></label><label>YOUR TITLE<input id="video-label" maxlength="100" placeholder="Name this beat"></label><div class="two"><label>START AT (SECONDS)<input id="video-start" type="number" value="0" min="0" step="0.1" required></label><label>LOAD INTO<select id="video-target"><option value="queue">Queue only</option><option value="0">Deck 1</option><option value="1">Deck 2</option></select></label></div><button class="primary">Add video</button></form>`);$('#video-form').onsubmit=e=>{e.preventDefault();run(async()=>{const parsed=parseYouTubeURL($('#video-url').value);if(!parsed)throw new Error('Enter a valid YouTube watch, Shorts or youtu.be link.');const videoId=typeof parsed==='string'?parsed:parsed.videoId;const t={id:crypto.randomUUID(),source:'youtube',videoId,title:$('#video-label').value.trim()||`YouTube · ${videoId}`,start:Math.max(0,Number($('#video-start').value))};const target=$('#video-target').value;if(target!=='queue'){if(locked)throw new Error('Unlock before loading a video.');if(video.decks[+target].playing&&!await confirmAction('Replace playing video?','Playback on this deck will stop.'))return;await video.load(+target,t);}else{queue.push(t);await saveQueue();}close();render();toast(target==='queue'?'Video added to queue':'Video cued. Press Play to start.');});};}
async function prepareTrack(id){const row=await store.getTrack(id);if(!row)throw new Error('Track missing.');const t=row.track;modal(`<h2>Prepare track</h2><p class="note">Preparation does not move a playing deck. Start time and BPM are applied on the next load.</p><form id="prepare-form" class="stack"><label>TITLE<input id="prepare-title" value="${esc(t.title)}" required maxlength="100"></label><label>ARTIST<input id="prepare-artist" value="${esc(t.artist||'')}" maxlength="100"></label><div class="two"><label>BPM (MANUAL)<input id="prepare-bpm" type="number" min="30" max="300" step="0.1" value="${t.bpm||''}" placeholder="Unknown"></label><label>START (SECONDS)<input id="prepare-start" type="number" min="0" step="0.1" value="${t.start||0}"></label></div><button class="primary">Save preparation</button><button type="button" id="prepare-queue">＋ Add to live queue</button><button type="button" id="prepare-delete">Remove from collection…</button></form>`);const save=async()=>{const updated={...t,title:$('#prepare-title').value.trim(),artist:$('#prepare-artist').value.trim(),bpm:Number($('#prepare-bpm').value)||0,start:Math.max(0,Number($('#prepare-start').value)||0)};if(!updated.title)throw new Error('Give the track a title.');await store.saveTrack(updated,row.blob);tracks=await store.listTracks();return updated;};$('#prepare-form').onsubmit=e=>{e.preventDefault();run(async()=>{await save();close();render();toast('Track preparation saved.');});};$('#prepare-queue').onclick=()=>run(async()=>{queue.push({...await save()});await saveQueue();close();render();toast('Added to live queue.');});$('#prepare-delete').onclick=()=>run(async()=>{if(await confirmAction('Remove this import?','Saved sessions using this file will need it imported again.')){await store.deleteTrack(id);tracks=await store.listTracks();close();render();}});}
async function next(){if(locked)throw new Error('Unlock before loading the next track.');const idx=queue.findIndex(t=>(mode==='video')===(t.source==='youtube'));if(idx<0)throw new Error('Add a track for the current source to the queue.');const t=queue[idx],i=state().crossfade<=.5?1:0;if(mode==='audio'){if(!await loadTrack(i,t.id))return;engine.seek(i,t.start||0);}else{if(video.decks[i].playing&&!await confirmAction('Replace the incoming video?','This video is already playing.'))return;await video.load(i,t);}prepared={...t,deck:i};queue.splice(idx,1);await saveQueue();render();toast(`Deck ${i+1} prepared. Start it when ready.`);}
async function fade(i){if(!state().decks[i].playing)throw new Error(`Start Deck ${i+1} before fading.`);if(mode==='audio'){engine.fadeTo(i,fadeSeconds);}else{const result=await video.fadeTo(i,fadeSeconds);if(!result.cancelled&&settings.stopOutgoing)video.pause(1-i);}haptic();}
async function cut(i){if(mode==='audio'){await engine.play(i);engine.setCrossfade(i);if(settings.stopOutgoing)engine.pause(1-i);}else{const r=await video.cutTo(i);if(r.cancelled)return false;if(settings.stopOutgoing)video.pause(1-i);}haptic();return true;}
async function toggle(i){await state().toggle(i);haptic();update();}
async function saveSession(){const name=$('#session-name').value.trim();if(!name)throw new Error('Give this session a name.');await store.saveSession(name,{audio:engine.snapshot(),video:video.decks.map((d,i)=>d.track?{...d.track,start:video.getPosition(i),repeat:d.repeat}:null),mode,queue,videoCrossfade:video.crossfade});sessions=await store.listSessions();render();toast('Session saved. Imports remain on this device.');}
async function restoreSession(id){if(locked)throw new Error('Unlock before restoring a session.');if(!await confirmAction('Restore session?','Current playback will pause. The saved session will load paused.'))return;const saved=await store.getSession(id);if(!saved)throw new Error('Saved session is missing.');engine.decks.forEach((_,i)=>engine.pause(i));video.pauseAll();const data=saved.data;await engine.restore(data.audio,id=>store.getTrack(id));queue=data.queue||[];await saveQueue();prepared=null;await setMode(data.mode||'audio');if(data.mode==='video'){for(let i=0;i<2;i++)if(data.video[i]){await video.load(i,data.video[i]);if(data.video[i].repeat)video.setRepeat(i,data.video[i].repeat);}video.setCrossfade(data.videoCrossfade??.5);}route='challenge';render();toast('Session restored paused. Press Play when ready.');}
async function recordToggle(){if(engine.recording){toast('Saving recording…');await engine.stopRecording();await recordingSave;}else{if(!engine.decks.some(d=>d.playing))throw new Error('Start a local deck before recording.');await engine.startRecording();toast('Recording local master audio.');}render();}
async function exportRecording(id){const r=await store.getRecording(id);if(!r)throw new Error('Recording is missing.');const ext=r.mime.includes('mp4')?'m4a':'webm';const name=`Mixline-${new Date(r.created).toISOString().replace(/[:.]/g,'-')}.${ext}`;if(r.size>64*1024*1024)throw new Error('This take exceeds the 64 MB export limit. Keep future takes shorter.');if(window.MixlineAndroid){const reader=new FileReader();reader.onload=()=>native('export',{name,mime:r.mime.split(';')[0],base64:String(reader.result).split(',')[1]});reader.onerror=()=>error(new Error('Could not read recording for export.'));reader.readAsDataURL(r.blob);}else{const url=URL.createObjectURL(r.blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}}
let customLoopStart=0;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;run(async()=>{
if(d.route)return navigate(d.route);
if(d.mode)return setMode(d.mode);
if(b.id==='lock'){locked=!locked;b.setAttribute('aria-pressed',String(locked));b.innerHTML=icon('lock',16)+` <span>${locked?'Locked':'Lock'}</span>`;toast(locked?'Performance locked: loading, seeking and cue edits protected.':'Performance unlocked.');return;}
if('import' in d){if(locked)throw new Error('Unlock before importing.');$('#files').click();return;}
if('demo' in d)return demo();
if(d.play!==undefined)return toggle(+d.play);
if(d.videoPlay!==undefined){await video.toggle(+d.videoPlay);return;}
if(d.videoRetry!==undefined)return video.retry(+d.videoRetry);
if(d.videoSeek!==undefined){if(locked)throw new Error('Unlock before seeking.');const i=+d.videoSeek;video.seek(i,video.decks[i].track?.start||0);return;}
if(d.mainCue!==undefined){const i=+d.mainCue;if(mode==='video'){video.pause(i);video.seek(i,video.decks[i].track?.start||0);}else engine.cue(i);haptic();return;}
if(d.cue!==undefined){engine.cue(+d.cue);flash(b);haptic();return;}
if(d.sync!==undefined){engine.sync(+d.sync);toast('Tempo matched and phase aligned once.');return;}
if(d.focus!==undefined){selectedDeck=+d.focus;return navigate('focus');}
if(d.load!==undefined)return loadTrack(+d.load,d.id);
if(d.prepare)return prepareTrack(d.prepare);
if(d.filter){filter=d.filter;render();return;}
if('clearFilter' in d){filter='all';search='';render();return;}
if('addVideo' in d)return addVideo();
if('localBed' in d){engine.setCrossfade(0);await engine.toggle(0);return;}
if('videoRepeat' in d){const i=+d.videoRepeat;const vd=video.decks[i];video.setRepeat(i,{enabled:!vd.repeat?.enabled,start:vd.track?.start||0});toast('Video repeat preference updated. Seek-based repeats may have gaps.');render();return;}
if('next' in d)return next();
if('nextCut' in d){if(prepared){if(await cut(prepared.deck)){prepared=null;render();}}return;}
if(d.cut!==undefined)return cut(+d.cut);
if(d.fade!==undefined)return fade(+d.fade);
if(d.queueUp!==undefined){if(locked)throw new Error('Unlock before editing queue order.');const i=+d.queueUp;if(i>0)[queue[i-1],queue[i]]=[queue[i],queue[i-1]];await saveQueue();render();return;}
if(d.queueRemove!==undefined){if(locked)throw new Error('Unlock before editing the queue.');const i=+d.queueRemove;undoQueue={i,t:queue.splice(i,1)[0]};await saveQueue();render();return;}
if('queueUndo' in d){if(undoQueue){queue.splice(undoQueue.i,0,undoQueue.t);undoQueue=null;await saveQueue();render();}return;}
if(d.selectDeck!==undefined){selectedDeck=+d.selectDeck;render();return;}
if(d.hotcue!==undefined){flash(b);const slot=+d.hotcue;if(engine.decks[selectedDeck].cues[slot]===null){if(locked)throw new Error('Unlock to set a new cue.');engine.setCue(selectedDeck,slot);}else engine.goCue(selectedDeck,slot);haptic();render();return;}
if('slip' in d){engine.setSlip(selectedDeck,!engine.decks[selectedDeck].slip);render();return;}
if('clearCues' in d){if(locked)throw new Error('Unlock before clearing cues.');if(await confirmAction('Clear this deck’s cues?','All eight hot cues on this deck will be removed.')){engine.decks[selectedDeck].cues.fill(null);render();}return;}
if('startHere' in d){if(locked)throw new Error('Unlock before changing the start cue.');engine.setStartCue(selectedDeck,engine.position(selectedDeck));toast('Start cue saved for this deck. Save a session to keep it.');return;}
if(d.loop!==undefined){engine.loop(selectedDeck,+d.loop);render();return;}
if('loopIn' in d){customLoopStart=engine.position(selectedDeck);toast(`Loop in set at ${time(customLoopStart)}`);return;}
if('loopOut' in d){engine.setLoopPoints(selectedDeck,customLoopStart,engine.position(selectedDeck));render();return;}
if(d.jump!==undefined){if(locked)throw new Error('Unlock before jumping.');engine.nudge(selectedDeck,+d.jump);return;}
if('tap' in d){engine.tap(selectedDeck);toast(`Tempo: ${engine.decks[selectedDeck].bpm.toFixed(1)} BPM`);return;}
if('bpmEdit' in d){modal(`<h2>Set deck tempo</h2><form id="bpm-form" class="stack"><label>BPM<input id="bpm-input" type="number" min="30" max="300" step="0.1" value="${engine.decks[selectedDeck].bpm||120}" required></label><button class="primary">Set BPM</button></form>`);$('#bpm-form').onsubmit=e=>{e.preventDefault();engine.setBpm(selectedDeck,+$('#bpm-input').value);close();render();};return;}
if(d.resetChannel!==undefined){const i=+d.resetChannel;for(const band of ['low','mid','high'])engine.setEQ(i,band,0);engine.setFilter(i,0);engine.setGain(i,1);render();return;}
if('resetFx' in d){engine.setFX(selectedDeck,'echo',0);engine.setFX(selectedDeck,'reverb',0);engine.setFilter(selectedDeck,0);render();return;}
if('echoOut' in d){const incoming=1-selectedDeck;if(!engine.decks[incoming].playing)throw new Error('Start the other deck before the echo-out transition.');engine.setFX(selectedDeck,'echo',.65);engine.fadeTo(incoming,4);return;}
if(d.sample!==undefined){flash(b);await engine.sampler(+d.sample);haptic();return;}
if('record' in d)return recordToggle();
if(d.export)return exportRecording(d.export);
if(d.deleteRecording){if(await confirmAction('Delete recording?','Export a copy first if you want to keep this take.')){await store.deleteRecording(d.deleteRecording);recordings=await store.listRecordings();render();}return;}
if('saveSession' in d)return saveSession();
if(d.restoreSession)return restoreSession(d.restoreSession);
if(d.deleteSession){if(await confirmAction('Delete saved session?','Imported music will stay in your collection.')){await store.deleteSession(d.deleteSession);sessions=await store.listSessions();render();}return;}
if('saveSettings' in d){await store.setSetting('preferences',settingsDraft);settings={...settingsDraft};dirty=false;applySettings();$('#settings-status').textContent='Preferences saved.';toast('Preferences saved.');return;}
if('resetSettings' in d){settingsDraft={haptics:true,theme:'dark',curve:'blend',stopOutgoing:true,motion:'system'};$$('[data-setting]').forEach(e=>{if(e.type==='checkbox')e.checked=settingsDraft[e.dataset.setting];else e.value=settingsDraft[e.dataset.setting];});dirty=true;$('#settings-status').textContent='Defaults restored in draft. Save to apply.';return;}
if('diagnostics' in d){const estimate=await store.storageEstimate();modal(`<h2>Device test diagnostics</h2><p class="note">Mixline 4.0.0-test1<br>Audio context: ${esc(engine.ctx?.state||'not started')}<br>Sample rate: ${engine.ctx?.sampleRate||'—'} Hz<br>Reported base latency: ${engine.ctx?.baseLatency?`${Math.round(engine.ctx.baseLatency*1000)} ms`:'unavailable'}<br>Storage used: ${estimate.usage?(estimate.usage/1048576).toFixed(1)+' MB':'unavailable'}<br>Native bridge: ${window.MixlineAndroid?'connected':'browser mode'}<br>Microphone recording: not enabled<br><br>Reported engine latency is not a physical touch-to-sound measurement.</p>`);return;}
});});
document.addEventListener('input',e=>{const el=e.target,d=el.dataset;try{
if(el.id==='crossfader'){const before=state().crossfade,value=+el.value;state().setCrossfade(value);if((before<.5&&value>=.5)||(before>.5&&value<=.5)||(value===0&&before!==0)||(value===1&&before!==1))haptic();return;}
if(el.id==='search'){search=el.value;const pos=el.selectionStart;render();$('#search').focus();$('#search').setSelectionRange?.(pos,pos);return;}
if(d.rate!==undefined){engine.setRate(+d.rate,+el.value);const out=$(`[data-rate-value="${d.rate}"]`);if(out)out.textContent=`${((+el.value-1)*100).toFixed(1)}%`;}
if(d.gain!==undefined)engine.setGain(+d.gain,+el.value);
if(d.eq){const [i,b]=d.eq.split(':');engine.setEQ(+i,b,+el.value);}
if(d.filterKnob!==undefined)engine.setFilter(+d.filterKnob,+el.value);
if(d.fx){const [i,fx]=d.fx.split(':');engine.setFX(+i,fx,+el.value);}
if('master' in d)engine.setMaster(+el.value);
const output=el.closest('.control')?.querySelector('output');if(output)output.textContent=(+el.value).toFixed(1);
if(d.setting){settingsDraft[d.setting]=el.type==='checkbox'?el.checked:el.value;dirty=true;$('#settings-status').textContent='Unsaved changes. Save to apply.';}
}catch(err){error(err);}});
document.addEventListener('change',e=>{if(e.target.id==='fade-seconds')fadeSeconds=+e.target.value;});
$('#files').addEventListener('change',()=>run(async()=>{const files=[...$('#files').files];if(!files.length)return;busy=true;let count=0;try{for(const file of files){if(file.size>150*1024*1024){toast(`${file.name}: larger than the 150 MB import limit.`);continue;}await store.saveTrack({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'Local import',source:'local',bpm:0,start:0},file);count++;}tracks=await store.listTracks();route='library';render();toast(`${count} audio file${count===1?'':'s'} stored on this device.`);}finally{busy=false;$('#files').value='';}}));
function bindGestures(){for(const el of $$('[data-wave],[data-platter]')){const isPlatter=el.dataset.platter!==undefined,i=+(isPlatter?el.dataset.platter:el.dataset.wave);let drag=null;el.addEventListener('pointerdown',e=>{if(locked){toast('Unlock to scrub or seek.');return;}if(!engine.decks[i].track)return;e.preventDefault();el.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,p:engine.position(i)};if(isPlatter)engine.startScratch(i);else{const box=el.getBoundingClientRect();el.dataset.preview=String(Math.min(1,Math.max(0,(e.clientX-box.left)/box.width)));}});el.addEventListener('pointermove',e=>{if(!drag)return;const box=el.getBoundingClientRect();if(isPlatter)engine.scratchTo(i,Math.max(0,drag.p+(e.clientX-drag.x)/box.width*5));else el.dataset.preview=String(Math.min(1,Math.max(0,(e.clientX-box.left)/box.width)));});const finish=e=>{if(!drag)return;if(isPlatter)engine.endScratch(i);else{const box=el.getBoundingClientRect();engine.seek(i,Math.min(1,Math.max(0,(e.clientX-box.left)/box.width))*engine.decks[i].duration);}delete el.dataset.preview;drag=null;};el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',()=>{if(isPlatter)engine.endScratch(i);delete el.dataset.preview;drag=null;});el.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(!locked)engine.seek(i,engine.position(i)+(e.key==='ArrowRight'?1:-1));}});}}
function sizeVideoLayout(){const layout=$('#layout');if(mode==='video'){const top=layout.getBoundingClientRect().top,bottom=$('#dock').getBoundingClientRect().top;layout.style.height=Math.max(100,bottom-top-8)+'px';}else layout.style.height='';}
window.addEventListener('resize',()=>requestAnimationFrame(sizeVideoLayout));
let lastNativePlaying=false;
function enforceVideoVisibility(){if(mode!=='video'||!video.decks.some(d=>d.playing))return;const dockTop=$('#dock').getBoundingClientRect().top;for(let i=0;i<2;i++){if(!video.decks[i].playing)continue;const box=$(`#video-player-${i}`).getBoundingClientRect();if(box.width<200||box.height<200||box.top<0||box.bottom>dockTop+1){video.pauseAll();toast('Video paused because a player is out of view. Rotate the phone or scroll the player fully into view to resume.');break;}}}
setInterval(enforceVideoVisibility,250);
function update(){const live=state();for(let i=0;i<2;i++){const d=engine.decks[i],pos=engine.position(i);const card=$(`[data-deck="${i}"]`);card?.classList.toggle('playing',d.playing);const companion=$(`[data-companion="${i}"]`);if(companion){companion.querySelector('small').textContent=`DECK ${i+1} · ${d.playing?'PLAYING':d.track?'READY':'EMPTY'}`;const cp=companion.querySelector('[data-play]');if(cp&&cp.dataset.playing!==String(d.playing)){cp.innerHTML=playIcon(d.playing);cp.dataset.playing=String(d.playing);cp.classList.toggle('engaged',d.playing);}}const ds=$(`[data-deck-state="${i}"]`);if(ds)ds.textContent=d.scratching?'Scratching':d.playing?'Playing':d.track?'Ready':'Empty';card?.classList.toggle('scratching',!!d.scratching);const flag=$(`[data-loop-flag="${i}"]`);if(flag)flag.hidden=!d.loop;const platter=card?.querySelector('.vinyl');if(platter&&!reducedMotion())platter.style.transform=`rotate(${pos*200}deg)`;const t=$(`[data-time="${i}"]`);if(t)t.textContent=`${time(pos)} / ${time(d.duration)}`;const bpm=$(`[data-bpm="${i}"]`);if(bpm)bpm.textContent=`${d.bpm?(d.bpm*d.rate).toFixed(1):'—'} BPM`;const play=card?.querySelector('[data-play]');if(play){if(play.dataset.playing!==String(d.playing)){play.innerHTML=playIcon(d.playing);play.dataset.playing=String(d.playing);}play.classList.toggle('engaged',d.playing);play.setAttribute('aria-label',`${d.playing?'Pause':'Play'} deck ${i+1}`);}$$(`[data-meter="${i}"]`).forEach(m=>{m.style.transform=`scaleX(${Math.min(1,engine.meter(i)*1.3)})`;});const dock=$(`#dock-play-${i}`);if(dock.dataset.playing!==String(live.decks[i].playing)){dock.innerHTML=`${i?'02 ':''}${playIcon(live.decks[i].playing)}${i?'':' 01'}`;dock.dataset.playing=String(live.decks[i].playing);}dock.classList.toggle('engaged',live.decks[i].playing);const vd=video.decks[i];$(`#video-player-${i}`)?.closest('.video-card')?.setAttribute('data-state',vd.state);$(`#video-title-${i}`).textContent=vd.track?.title||(i?'Prepare the next beat':'Load your first video');$(`#video-status-${i}`).textContent=vd.error||`${vd.state||'Empty'}${vd.track?' · Player level '+Math.round(vd.volume||0)+'%':''}`;$(`#video-open-${i}`).href=vd.track?video.getURL(i):'https://www.youtube.com/';}
const x=live.crossfade??.5;if(document.activeElement!==$('#crossfader'))$('#crossfader').value=x;$('#blend-label').textContent=x<.02?'DECK 1':x>.98?'DECK 2':`BLEND · ${Math.round((1-x)*100)} / ${Math.round(x*100)}`;const playing=live.decks.filter(d=>d.playing).length;const fadeActive=!!live.fade;$('#dock').classList.toggle('fading',fadeActive);if(!$('#fade-status')){const liveRegion=document.createElement('span');liveRegion.id='fade-status';liveRegion.setAttribute('role','status');$('#dock').prepend(liveRegion);}$('#fade-status').textContent=fadeActive?'FADING · TOUCH FADER TO TAKE OVER':'';$('#dock-state').textContent=fadeActive?'FADING · MANUAL TAKEOVER':playing===2?'BOTH DECKS PLAYING':playing===1?`DECK ${live.decks[0].playing?1:2} PLAYING`:'PAUSED · READY WHEN YOU ARE';const any=engine.decks.some(d=>d.playing)||video.decks.some(d=>d.playing);if(any!==lastNativePlaying){native('playback',{playing:any});lastNativePlaying=any;}if($('#record-time'))$('#record-time').textContent=time(engine.recordingElapsed);
for(const c of $$('[data-canvas]')){const i=+c.dataset.canvas;drawWaveform(c,engine.decks[i],i,engine.position(i),engine.waveform(i));}}

let recordingSave=Promise.resolve();engine.addEventListener('recording',e=>{if(e.detail.active===false&&e.detail.blob){recordingSave=store.saveRecording(e.detail.blob).then(async()=>{recordings=await store.listRecordings();toast('Recording saved on this device.');if(route==='record')render();}).catch(error);}});
engine.addEventListener('transitionend',e=>{if(settings.stopOutgoing)engine.pause(1-e.detail.incoming);});
engine.addEventListener('change',update);video.addEventListener('change',update);video.addEventListener('error',e=>toast(e.detail?.message||'Video playback failed. Retry or open it in YouTube.'));engine.addEventListener('error',e=>toast(e.detail?.message||'Audio playback failed.'));
video.addEventListener('transitionend',e=>{if(settings.stopOutgoing)video.pause(1-e.detail.incoming);});
function applySettings(){document.body.classList.toggle('light',settings.theme==='light');engine.setCrossfadeCurve(settings.curve);setMotion(settings.motion||'system');}
window.mixlineLifecycle=reason=>{if(reason==='picker'){video.pauseAll();return;}const wasActive=engine.decks.some(d=>d.playing)||video.decks.some(d=>d.playing)||engine.recording;if(!wasActive)return;engine.decks.forEach((_,i)=>engine.pause(i));video.pauseAll();if(engine.recording)run(recordToggle);toast('Playback paused after an interruption. Press Play to resume.');};
window.mixlineBack=()=>{if($('#dialog').open){close();return true;}if(route!=='perform'){run(()=>navigate('perform'));return true;}return false;};
window.mixlineNativeResult=r=>{toast(r.message||(r.ok?'Export complete.':'Export cancelled.'));};
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(window.mixlinePickerActive)video.pauseAll();else window.mixlineLifecycle();}});
window.addEventListener('pagehide',()=>{engine.decks.forEach((_,i)=>engine.pause(i));video.pauseAll();});
window.addEventListener('offline',()=>{if(mode==='video')toast('You are offline. Local music is still available.');});
window.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
let lastPaint=0;function tick(now){if(!document.hidden&&now-lastPaint>=32){update();lastPaint=now;}requestAnimationFrame(tick);}
async function boot(){$$('nav button').forEach(b=>{const span=b.querySelector('span');if(span)span.innerHTML=icon({perform:'disc',challenge:'video',library:'library',tools:'pads'}[b.dataset.route]);});$('#lock').innerHTML=icon('lock',16)+' <span>Lock</span>';document.querySelector('header [data-route="settings"]').innerHTML=icon('settings',18);render();try{await store.init();settings=await store.getSetting('preferences',settings);queue=await store.getSetting('queue',[]);tracks=await store.listTracks();applySettings();render();const recovery=await store.getSession('recovery');if((recovery?.data?.audio?.decks.some(d=>d.track)||recovery?.data?.video?.some(Boolean)||recovery?.data?.queue?.length)){toast('A previous session is available in Sessions → Recovery.');sessions=await store.listSessions();}}catch(e){error(e);}requestAnimationFrame(tick);}
let saveRecoveryBusy=false;
setInterval(()=>{if(saveRecoveryBusy||(!engine.decks.some(d=>d.track)&&!video.decks.some(d=>d.track)&&!queue.length))return;saveRecoveryBusy=true;const data={audio:engine.snapshot(),mode,queue,video:video.decks.map((d,i)=>d.track?{...d.track,start:video.getPosition(i),repeat:d.repeat}:null),videoCrossfade:video.crossfade};store.saveSession('Recovery · last session',data,'recovery').catch(error).finally(()=>saveRecoveryBusy=false);},15000);
window.Mixline={engine,video,store,get state(){return {route,mode,queue,tracks,locked,prepared,settings};},navigate,setMode,loadTrack,demo};
boot();
